/**
 * Output format for biblatex-software, the BibLaTeX style for software
 * citations.
 *
 * Entries are generated by `@citation-js/plugin-bibtex`, then given the
 * entry type that matches what the SWHID points to, and a `swhid` field.
 *
 * @see https://ctan.org/pkg/biblatex-software
 *
 * @module output
 */

import { plugins } from '@citation-js/core'

import { parseSwhid } from './swhid.js'

/**
 * Pick the biblatex-software entry type for a SWHID:
 *
 * - `@codefragment` for a file (`cnt`)
 * - `@softwaremodule` for a directory below the root (`dir` with a `path`)
 * - `@softwareversion` for a release, a revision or a root directory
 * - `@software` for a snapshot, i.e. the project in general
 *
 * @param {string} swhid - SWHID, possibly with qualifiers
 * @return {string} entry type
 */
export function getEntryType(swhid) {
  const { type, qualifiers } = parseSwhid(swhid)

  switch (type) {
    case 'cnt':
      return 'codefragment'
    case 'dir':
      return qualifiers.path && qualifiers.path !== '/' ? 'softwaremodule' : 'softwareversion'
    case 'snp':
      return 'software'
    default:
      return 'softwareversion'
  }
}

/**
 * Format one CSL item as a biblatex-software entry. Items without a SWHID
 * are left as plain BibLaTeX.
 *
 * @param {Object} item - CSL item
 * @param {Object} [options] - options for the `biblatex` output format
 * @return {string} entry
 */
function formatItem(item, options) {
  const entry = plugins.output.format('biblatex', [item], options)
  const swhid = item.custom && item.custom.swhid
  if (!swhid) {
    return entry
  }

  return entry
    .replace(/^@\w+\{/, `@${getEntryType(swhid)}{`)
    .replace(/\}\s*$/, `\tswhid = {${swhid}},\n}\n\n`)
}

/**
 * Output formats registered by this plugin.
 *
 * - `biblatex-software`: CSL-JSON → biblatex-software text
 */
export const formats = {
  'biblatex-software'(data, options) {
    return data.map(item => formatItem(item, options)).join('')
  }
}
